CREATE TYPE lead_status AS ENUM ('new','contacted','follow_up','converted','completed','cancelled');
CREATE TYPE case_status AS ENUM ('new','documents','submitted','in_progress','awaiting_customer','completed','cancelled');
CREATE TYPE payment_status AS ENUM ('pending','paid','failed','refunded');
CREATE TABLE leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(120) NOT NULL,mobile varchar(30) NOT NULL,city varchar(100),service varchar(80) NOT NULL DEFAULT 'ثبت شرکت',notes text,source varchar(80) DEFAULT 'website',status lead_status NOT NULL DEFAULT 'new',internal_notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name varchar(120) NOT NULL,mobile varchar(30) NOT NULL UNIQUE,email varchar(180),national_id varchar(30),address text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES customers(id),lead_id uuid REFERENCES leads(id),title varchar(180) NOT NULL DEFAULT 'پرونده ثبت شرکت',status case_status NOT NULL DEFAULT 'new',notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES cases(id),title varchar(180) NOT NULL,notes text,completed boolean NOT NULL DEFAULT false,due_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES cases(id),name varchar(180) NOT NULL,url text NOT NULL,pathname text,mime_type varchar(120),size integer,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES cases(id),amount integer NOT NULL,description varchar(240) NOT NULL DEFAULT 'هزینه خدمات ثبت شرکت',status payment_status NOT NULL DEFAULT 'pending',authority varchar(180),paid_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE service_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),key varchar(80) NOT NULL UNIQUE,value text NOT NULL,active boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now());